import React, { useEffect, useState } from 'react';

const typingLines = [
  'name = "Chetanya Makkar"',
  'major = "Computer Science"',
  'minor = "Computational Finance"',
  'gpa = 3.76',
  'school = "University of Maryland"'
];

function App() {
  const [index, setIndex] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      setIndex((i) => (i + 1) % typingLines.length);
    }, 3500);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="bg-black text-green-400 min-h-screen flex items-center justify-center font-mono text-xl p-6">
      <div className="typewriter-text w-fit">{typingLines[index]}</div>
    </div>
  );
}

export default App;
